        for c in range(w):
            v = g[r][c]
            if v == bg:
                continue
            if sum(x != bg for row in g for x in row) < 2:
                continue
            # skip cells belonging to the long boundary bars
            if sum(x == v for x in g[r]) > 1:
                continue
            if sum(g[rr][c] == v for rr in range(h)) > 1:
                continue
            # Find a bar of this marker color on top/bottom and extend to it.
            top = any(x == v for x in g[0])
            bottom = any(x == v for x in g[h-1])
            if top and not bottom:
                for rr in range(r):
                    if g[rr][c] == bg:
                        g[rr][c] = v
            elif bottom and not top:
                for rr in range(r+1, h):
                    if g[rr][c] == bg:
                        g[rr][c] = v
            else:
                # With two same-color bars on opposite edges, connect marker
                # toward the nearest matching boundary.
                dist_top = r
                dist_bottom = h-1-r
                edge = 0 if dist_top <= dist_bottom else h-1
                span = range(r-1, -1, -1) if edge == 0 else range(r+1, h)
                for rr in span:
                    if g[rr][c] == bg:
                        g[rr][c] = v
    return g
